"use strict";

// The package's whole callable API is chosen AT RUNTIME by a class whose
// `extends` HERITAGE expression is a resolvable LOCAL CALL that RETURNS
// NORMALLY -- and whose returned VALUE is not a usable superclass:
//
//     function notAConstructor() { return 1; }
//     class Mode extends notAConstructor() {}
//
// This is NOT RWF-020's shape. `notAConstructor()` does not throw; it
// completes, every time, handing back `1`. ClassDefinitionEvaluation then
// fails its own heritage validation -- `1` is neither `null` nor a
// constructor -- and throws
// `TypeError: Class extends value 1 is not a constructor or null`. The
// class definition never completes, `Mode` is never bound, and module
// evaluation on this branch ends there.
//
// An analyzer that asks only "does the heritage CALL complete?" (RWF-020)
// answers "yes" and has nothing to fire on.
// See fixtures/commonjs-circular-import-invalid-class-heritage-ground-truth/
// for a real node-executed, ASSERTED proof.
const danger = require("./danger");

// The branch that reaches the vulnerable sink. Nothing in this file calls
// it: the ONLY way it ever runs is by being the module's exported value.
function dangerousOp(input) {
  return danger.explode(input);
}

// The branch that does not.
function safeOp(input) {
  return "safe:" + input;
}

// A resolvable local callable whose entire body is a single unconditional
// return of a numeric literal. It is definitely NOT abrupt -- RWF-020's
// `cannotCompleteNormally` refuses it, correctly. What it is, is a factory
// whose returned value is definitely non-constructable.
function notAConstructor() {
  return 1;
}

if (process.env.FIXTURE_LIB_MODE === "fast") {
  module.exports = dangerousOp;
  // Evaluating this class definition invokes `notAConstructor()`, which
  // RETURNS. The class definition then throws on heritage validation.
  class Mode extends notAConstructor() {}
}

module.exports = safeOp;
